def pin(b):return dict(bytes=len(b),sha256=hashlib.sha256(b).hexdigest())
def apply(target,case):
 if case not in DELTAS:raise ValueError('closed three lifecycle cases')
 root=Path(target)
 for n,(before,after)in DELTAS[case].items():
  p=root/n
  if before is None:
   if p.exists()or p.is_symlink():raise ValueError('fresh lifecycle support source')
  elif pin(p.read_bytes())!=before:raise ValueError('whole lifecycle candidate predecessor')
 for n,(before,after)in DELTAS[case].items():
  p=root/n;p.parent.mkdir(parents=True,exist_ok=True);p.write_bytes(after)
